import numpy as np

def feature(item, bins, capacity):
    """Sharp peak (width 5% of capacity) at room == item, scaled by how full the bin becomes (item/capacity)."""
    width = 0.05 * capacity
    if width <= 0:
        return np.zeros_like(bins, dtype=float)
    peak = np.exp(-np.abs(bins - item) / width)
    # weight the peak by the fraction of capacity the item fills: exact closure of a big item counts more
    fill = item / capacity if capacity > 0 else 0.0
    return peak * fill

import numpy as np

def feature(item, bins, capacity):
    """Remaining-room fraction of each candidate bin (bins / capacity), in [0, 1]."""
    return np.asarray(bins, dtype=float) / float(capacity)

