import numpy as np

def feature(item, bins, capacity):
    """Rank of each candidate's remaining room among all candidates, normalised to [-1, 1] (oldest-lowest wins)."""
    room = bins.astype(float)
    k = len(room)
    if k <= 1:
        return np.zeros(k)
    order = np.argsort(np.argsort(room, kind="stable"), kind="stable").astype(float)
    val = 1.0 - 2.0 * order / max(k - 1, 1)
    return val
